-- CLAUDE-272: the CI-failure store. Same end schema as
-- `../sqlite/0021_ci_failures.sql`, spelled per the CLAUDE-250 squash mapping
-- (`BIGINT` for every integer, `GENERATED BY DEFAULT AS IDENTITY` for the
-- autoincrement keys).

CREATE TABLE IF NOT EXISTS ci_failures (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    repo        TEXT NOT NULL,
    workflow_id TEXT NOT NULL,
    job_name    TEXT NOT NULL,
    infra_kind  TEXT,
    issue_key   TEXT,
    state       TEXT NOT NULL,
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS ci_failure_tests (
    failure_id BIGINT NOT NULL REFERENCES ci_failures(id),
    test_id    TEXT NOT NULL,
    UNIQUE (failure_id, test_id)
);
CREATE INDEX IF NOT EXISTS idx_ci_failure_tests_test_id ON ci_failure_tests(test_id);

CREATE TABLE IF NOT EXISTS ci_failure_runs (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    failure_id  BIGINT NOT NULL REFERENCES ci_failures(id),
    run_index   BIGINT NOT NULL,
    commit_sha  TEXT NOT NULL,
    branch      TEXT NOT NULL,
    pr_number   BIGINT,
    ts          TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ci_failure_runs_ts ON ci_failure_runs(ts);

CREATE TABLE IF NOT EXISTS agent_pull_requests (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    action_name  TEXT NOT NULL,
    issue_key    TEXT NOT NULL,
    host         TEXT NOT NULL,
    repo         TEXT NOT NULL,
    pr_number    BIGINT NOT NULL,
    head_branch  TEXT NOT NULL,
    fix_attempts BIGINT NOT NULL DEFAULT 0,
    state        TEXT NOT NULL,
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    UNIQUE (host, repo, pr_number)
);
CREATE INDEX IF NOT EXISTS idx_agent_pull_requests_issue_key ON agent_pull_requests(issue_key);
